package performance

// Delivery IDs are generated by the Gateway client for one received frame.
// Request IDs alone cannot distinguish accepted and terminal response frames.
func (s *AnalysisSnapshot) gatewayIntervals() {
	type delivery struct {
		received, offered, consumed *AnalysisEvent
		invalid                     bool
	}
	deliveries := make(map[string]*delivery)
	for i := range s.Events {
		e := &s.Events[i]
		if e.GatewayDeliveryID == "" {
			continue
		}
		key := e.ClockDomain + "/" + e.GatewayDeliveryID
		d := deliveries[key]
		if d == nil {
			d = &delivery{}
			deliveries[key] = d
		}
		var target **AnalysisEvent
		switch e.Name {
		case "gateway.frame.received":
			target = &d.received
		case "gateway.event.enqueue_offer", "gateway.response.enqueue_offer":
			target = &d.offered
		case "gateway.event.consumed", "gateway.response.consumed":
			target = &d.consumed
		default:
			continue
		}
		if *target != nil {
			d.invalid = true
		} else {
			*target = e
		}
	}
	if len(deliveries) == 0 {
		return
	}
	coverage := SourceCoverage{Source: "gateway_delivery", Integrity: "complete", Status: "unknown", Missing: []string{"independent_expected_delivery_count"}}
	for _, key := range sortedKeys(deliveries) {
		d := deliveries[key]
		if d.received != nil {
			coverage.Started++
			coverage.ObservedEvents++
		}
		if d.offered != nil {
			coverage.ObservedEvents++
		}
		if d.consumed != nil {
			coverage.ObservedEvents++
		}
		if d.invalid {
			coverage.Integrity = "incomplete"
			coverage.Status = "incomplete"
			s.problem("duplicate Gateway delivery boundary")
			continue
		}
		if d.received == nil || d.offered == nil || d.consumed == nil {
			coverage.Status = "incomplete"
			continue
		}
		if d.received.AnalysisIdentity != d.offered.AnalysisIdentity || d.received.AnalysisIdentity != d.consumed.AnalysisIdentity || d.offered.OffsetNS < d.received.OffsetNS || d.consumed.OffsetNS < d.offered.OffsetNS {
			coverage.Integrity = "incomplete"
			coverage.Status = "incomplete"
			s.problem("Gateway delivery identity or order conflicts")
			continue
		}
		coverage.Paired++
		for _, phase := range []struct {
			name, scope string
			start, end  *AnalysisEvent
		}{
			{"gateway.delivery.receive_to_offer", "controller_decode_and_route", d.received, d.offered},
			{"gateway.delivery.offer_to_consume", "controller_channel_offer_to_consume", d.offered, d.consumed},
		} {
			s.interval(stableAnalysisID("operation", key, phase.name), phase.name, "gateway", phase.scope, "observed", *phase.start, *phase.end, nil)
		}
	}
	if coverage.Status == "incomplete" {
		s.CoverageStatus = "incomplete"
	}
	s.Coverage = append(s.Coverage, coverage)
}
